"use strict";
import styled from "styled-components";
import { formatUnits } from "ethers/lib/utils";
import { Trans } from "react-i18next";
const DetailsContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  background: ${({ theme }) => theme.surface2};
  border-radius: 12px;
`;
const DetailRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
`;
const DetailLabel = styled.span`
  font-size: 14px;
  color: ${({ theme }) => theme.neutral2};
`;
const DetailValue = styled.span`
  font-size: 14px;
  color: ${({ theme }) => theme.neutral1};
  font-weight: 500;
`;
const Divider = styled.div`
  height: 1px;
  background: ${({ theme }) => theme.surface3};
`;
export function BridgeDetails({ quote }) {
  const formatTime = (seconds) => {
    if (!seconds) return "Unknown";
    if (seconds < 60) return `~${seconds}s`;
    const minutes = Math.floor(seconds / 60);
    return `~${minutes}m`;
  };
  const formatFee = (feeWei) => {
    try {
      const feeEth = formatUnits(feeWei, 18);
      return `${Number(feeEth).toFixed(6)} ETH`;
    } catch {
      return "Calculating...";
    }
  };
  return <DetailsContainer>
      <DetailRow>
        <DetailLabel>
          <Trans>Route</Trans>
        </DetailLabel>
        <DetailValue>{quote.route || "Stargate Bridge"}</DetailValue>
      </DetailRow>

      <DetailRow>
        <DetailLabel>
          <Trans>Estimated Time</Trans>
        </DetailLabel>
        <DetailValue>{formatTime(quote.estimatedTime)}</DetailValue>
      </DetailRow>

      <DetailRow>
        <DetailLabel>
          <Trans>Bridge Fee</Trans>
        </DetailLabel>
        <DetailValue>{quote.fee ? formatFee(quote.fee) : "Calculating..."}</DetailValue>
      </DetailRow>

      <Divider />

      <DetailRow>
        <DetailLabel>
          <Trans>Minimum Received</Trans>
        </DetailLabel>
        <DetailValue>
          {(Number(quote.dstAmountMin || quote.amountOut) / Math.pow(10, 18)).toFixed(6)}
        </DetailValue>
      </DetailRow>
    </DetailsContainer>;
}
