"use strict";
const STARGATE_API_BASE_URL = "https://stargate.finance/api/v1";
class StargateApiClient {
  baseUrl;
  constructor(baseUrl = STARGATE_API_BASE_URL) {
    this.baseUrl = baseUrl;
  }
  /**
   * Fetch a bridge quote for token transfer
   */
  async getQuote(request) {
    try {
      const slippageBps = request.slippage || 50;
      const amountBigInt = BigInt(request.amountIn);
      const dstAmountMin = amountBigInt * BigInt(1e4 - slippageBps) / BigInt(1e4);
      const params = new URLSearchParams({
        srcChainKey: request.srcChainKey,
        srcToken: request.srcTokenAddress,
        dstChainKey: request.dstChainKey,
        dstToken: request.dstTokenAddress,
        srcAmount: request.amountIn,
        dstAmountMin: dstAmountMin.toString(),
        srcAddress: request.sender,
        dstAddress: request.receiver || request.sender,
        slippage: slippageBps.toString()
      });
      const response = await fetch(`${this.baseUrl}/quotes?${params.toString()}`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json"
        }
      });
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const message = errorData.error?.message || errorData.message || `HTTP ${response.status}: ${response.statusText}`;
        return {
          success: false,
          error: "API_ERROR",
          message
        };
      }
      const data = await response.json();
      if (data.quotes && Array.isArray(data.quotes) && data.quotes.length > 0) {
        const sortedQuotes = [...data.quotes].sort((a, b) => {
          const aTime = a.duration?.estimated || Infinity;
          const bTime = b.duration?.estimated || Infinity;
          return aTime - bTime;
        });
        const quote = sortedQuotes[0];
        const totalFee = quote.fees?.reduce((sum, fee) => sum + BigInt(fee.amount), BigInt(0)).toString() || "0";
        return {
          success: true,
          ...quote,
          // Add compatibility properties for existing UI
          amountIn: quote.srcAmount,
          amountOut: quote.dstAmount,
          fee: totalFee,
          estimatedTime: quote.duration?.estimated,
          transactions: quote.steps?.map((step) => step.transaction) || []
        };
      }
      return {
        success: false,
        error: "NO_QUOTES",
        message: data.error?.message || "No quotes available for this route"
      };
    } catch (error) {
      return {
        success: false,
        error: "NETWORK_ERROR",
        message: error instanceof Error ? error.message : "Unknown error occurred"
      };
    }
  }
  /**
   * Get all supported chains
   */
  async getChains() {
    try {
      const response = await fetch(`${this.baseUrl}/chains`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json"
        }
      });
      if (!response.ok) {
        return {
          success: false,
          error: "API_ERROR",
          message: `HTTP ${response.status}: ${response.statusText}`
        };
      }
      const data = await response.json();
      if (data && data.chains) {
        return {
          success: true,
          chains: data.chains
        };
      }
      if (Array.isArray(data)) {
        return {
          success: true,
          chains: data
        };
      }
      return {
        success: false,
        error: "INVALID_RESPONSE",
        message: "Unexpected API response format"
      };
    } catch (error) {
      return {
        success: false,
        error: "NETWORK_ERROR",
        message: error instanceof Error ? error.message : "Unknown error occurred"
      };
    }
  }
  /**
   * Get all supported tokens
   * @param srcChainKey - Optional filter by source chain key (e.g., "ethereum", "arbitrum")
   * @param srcToken - Optional filter by token address on source chain
   */
  async getTokens(srcChainKey, srcToken) {
    try {
      const params = new URLSearchParams();
      if (srcChainKey) params.append("srcChainKey", srcChainKey);
      if (srcToken) params.append("srcToken", srcToken);
      const queryString = params.toString();
      const url = queryString ? `${this.baseUrl}/tokens?${queryString}` : `${this.baseUrl}/tokens`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          "Content-Type": "application/json"
        }
      });
      if (!response.ok) {
        return {
          success: false,
          error: "API_ERROR",
          message: `HTTP ${response.status}: ${response.statusText}`
        };
      }
      const data = await response.json();
      if (data && data.tokens) {
        return {
          success: true,
          tokens: data.tokens
        };
      }
      if (Array.isArray(data)) {
        return {
          success: true,
          tokens: data
        };
      }
      return {
        success: false,
        error: "INVALID_RESPONSE",
        message: "Unexpected API response format"
      };
    } catch (error) {
      return {
        success: false,
        error: "NETWORK_ERROR",
        message: error instanceof Error ? error.message : "Unknown error occurred"
      };
    }
  }
  /**
   * Check bridge transaction status
   */
  async getBridgeStatus(txHash, srcChainId) {
    try {
      const response = await fetch(`${this.baseUrl}/status/${srcChainId}/${txHash}`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json"
        }
      });
      if (!response.ok) {
        return {
          success: false,
          error: "API_ERROR",
          message: `HTTP ${response.status}: ${response.statusText}`
        };
      }
      return await response.json();
    } catch (error) {
      return {
        success: false,
        error: "NETWORK_ERROR",
        message: error instanceof Error ? error.message : "Unknown error occurred"
      };
    }
  }
}
export const stargateClient = new StargateApiClient();
