"use strict";
import { useQuery } from "@tanstack/react-query";
import { stargateClient } from "api/stargate";
export function useStargateChains() {
  return useQuery({
    queryKey: ["stargate-chains"],
    queryFn: async () => {
      const response = await stargateClient.getChains();
      if (!response.success) {
        throw new Error(response.message || "Failed to fetch chains");
      }
      return response;
    },
    staleTime: 5 * 60 * 1e3,
    // 5 minutes
    gcTime: 10 * 60 * 1e3,
    // 10 minutes
    retry: 3
  });
}
