"use strict";
import { useQuery } from "@tanstack/react-query";
import { stargateClient } from "api/stargate";
export function useStargateQuote({ request, enabled = true }) {
  return useQuery({
    queryKey: ["stargate-quote", request],
    queryFn: async () => {
      if (!request) {
        throw new Error("No quote request provided");
      }
      const response = await stargateClient.getQuote(request);
      if (!response.success) {
        const error = new Error(response.message || "Failed to fetch quote");
        if (response.error === "NO_QUOTES" || response.error === "API_ERROR") {
          error.isClientError = true;
        }
        throw error;
      }
      return response;
    },
    enabled: enabled && request !== null,
    staleTime: 3e4,
    // 30 seconds
    gcTime: 6e4,
    // 1 minute (formerly cacheTime)
    retry: (failureCount, error) => {
      if (error?.isClientError) {
        return false;
      }
      return failureCount < 2;
    },
    refetchInterval: 3e4
    // Refresh every 30 seconds
  });
}
